import { render, screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { IssueList } from '../components/IssueList'
import type { Issue } from '../types'
import { makeIssue, sampleApiIssues } from './fakeApi'

const issues: Issue[] = sampleApiIssues

describe('IssueList', () => {
  it('shows every issue to start with', () => {
    render(<IssueList issues={issues} />)
    expect(screen.getAllByRole('listitem')).toHaveLength(4)
    expect(screen.getByText('Showing 4 of 4 issues')).toBeInTheDocument()
  })

  it('has a "Filter by status" dropdown that starts on all', () => {
    render(<IssueList issues={issues} />)
    expect(screen.getByLabelText('Filter by status')).toHaveValue('all')
  })

  it('offers all, open, in-progress and closed', () => {
    render(<IssueList issues={issues} />)
    const names = within(screen.getByLabelText('Filter by status'))
      .getAllByRole('option')
      .map((o) => o.textContent)
    expect(names).toEqual(['all', 'open', 'in-progress', 'closed'])
  })

  it('shows only open issues when open is chosen', async () => {
    render(<IssueList issues={issues} />)
    await userEvent.selectOptions(screen.getByLabelText('Filter by status'), 'open')
    expect(screen.getAllByRole('listitem')).toHaveLength(2)
    expect(screen.getByText('Showing 2 of 4 issues')).toBeInTheDocument()
    expect(screen.getByRole('heading', { name: 'Login button does nothing' })).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Typo on the home page' })).not.toBeInTheDocument()
  })

  it('shows everything again when all is chosen after a filter', async () => {
    render(<IssueList issues={issues} />)
    const select = screen.getByLabelText('Filter by status')
    await userEvent.selectOptions(select, 'closed')
    expect(screen.getAllByRole('listitem')).toHaveLength(1)
    await userEvent.selectOptions(select, 'all')
    expect(screen.getAllByRole('listitem')).toHaveLength(4)
  })

  it('says "No issues to show." when the list is empty', () => {
    render(<IssueList issues={[]} />)
    expect(screen.getByText('No issues to show.')).toBeInTheDocument()
    expect(screen.getByText('Showing 0 of 0 issues')).toBeInTheDocument()
  })

  it('says "No issues to show." when the filter matches nothing', async () => {
    render(<IssueList issues={issues.filter((i) => i.status === 'open')} />)
    await userEvent.selectOptions(screen.getByLabelText('Filter by status'), 'closed')
    expect(screen.getByText('No issues to show.')).toBeInTheDocument()
    expect(screen.getByText('Showing 0 of 2 issues')).toBeInTheDocument()
  })

  it('does not change the issues it was given', async () => {
    const mine: Issue[] = [
      makeIssue(1, { _id: 'z', title: 'Zebra crossing is missing', status: 'open' }),
      makeIssue(2, { _id: 'm', title: 'Menu overlaps the logo', status: 'closed' }),
      makeIssue(3, { _id: 'a', title: 'Alt text is missing', status: 'open' }),
    ]
    render(<IssueList issues={mine} />)
    await userEvent.selectOptions(screen.getByLabelText('Filter by status'), 'open')
    expect(mine.map((i) => i._id)).toEqual(['z', 'm', 'a'])
  })

  it('passes onSelect through to each card, using the _id', async () => {
    const onSelect = vi.fn()
    render(<IssueList {...({ issues, onSelect } as Parameters<typeof IssueList>[0])} />)
    const views = screen.getAllByRole('button', { name: 'View' })
    expect(views).toHaveLength(4)
    await userEvent.click(views[1]!)
    expect(onSelect).toHaveBeenCalledWith('000000000000000000000002')
  })
})
